atts.custom_css:
selector{align-self:flex-start;width:auto;}
selector::before { content:"";position:absolute;top:-2px;right:-2px;bottom:-2px;left:-2px;inset:-2px;transform:translateX(-18%);transition:transform 700ms cubic-bezier(0.2, 0.8, 0.2, 1), opacity 700ms cubic-bezier(0.2, 0.8, 0.2, 1);transition-property:transform, opacity;transition-duration:700ms, 700ms;transition-timing-function:cubic-bezier(0.2, 0.8, 0.2, 1), cubic-bezier(0.2, 0.8, 0.2, 1);background-color:initial;background-image:linear-gradient(115deg, rgba(255, 255, 255, 0.96) 0%, rgba(209, 213, 219, 0.8) 22%, rgba(255, 255, 255, 0.6) 42%, rgba(148, 163, 184, 0.18) 58%, rgba(255, 255, 255, 0.86) 76%, rgba(255, 255, 255, 0.98) 100%);opacity:0.74;filter:blur(14px); }
selector:hover::before { transform:translateX(8%) !important;opacity:0.92 !important; }
:where(selector){line-height:20px;text-align:center;transition:all;}
